"use client";

/**
 * FLAGSHIP — "Combined" greatest-hits game-server landing template.
 *
 * Curated merge of the three approved preview directions, composed into one
 * coherent premium page (NOT a stack of all three):
 *
 *   • from CINEMATIC — the full-bleed key-art hero with a navy-scrimmed
 *     asymmetric split + a genuinely-animated LIVE server panel (ticking player
 *     count, a drawn TPS graph, a streaming console) and slow scroll parallax;
 *     plus the plan cards and the blurred-art cinematic CTA.
 *   • from EDITORIAL — the numbered buying-reasons rail with the scroll-linked
 *     progress spine, beside a STICKY recommended plan card whose 47-second
 *     deploy ring counts up as it pins.
 *   • from COMMAND DECK — a HUD/console deploy beat: a glass terminal that types
 *     its boot sequence to "✓ online in 47s" next to animated telemetry gauges.
 *
 * Reuses the shared kit hooks/atoms + the scoped `pv-*` motion system so it
 * stays in the same design language. Everything respects prefers-reduced-motion.
 *
 * Net-new, PREVIEW-ONLY. Touches no live page or shared component.
 */

import Link from "next/link";
import { useState } from "react";
import type { PreviewGame } from "./data";
import {
  usePrefersReducedMotion,
  useInViewOnce,
  useJitter,
  useCountUp,
  useParallax,
  useScrollProgress,
  useTypedLines,
  StarRow,
  ReasonIcon,
} from "./kit";
import { GameLogo } from "@/components/marketing/GameLogo";
import {
  IconBolt,
  IconShield,
  IconNvme,
  IconGlobe,
  IconUsers,
  IconClock,
  IconCheck,
} from "@/components/marketing/icons";

/* ── Live TPS sparkline — draws on view, pulsing playhead (from Cinematic) ── */
function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
  const w = 220;
  const h = 46;
  const min = 19.5;
  const max = 20.2;
  const step = w / (pts.length - 1);
  const coords = pts.map((v, i) => {
    const x = i * step;
    const y = h - ((v - min) / (max - min)) * h;
    return [x, y] as const;
  });
  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
  const area = `${line} L${w} ${h} L0 ${h} Z`;
  const [ex, ey] = coords[coords.length - 1];
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
      <defs>
        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
          <stop offset="100%" stopColor={accent} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill="url(#pv-cmb-tps-fill)" />
      <path
        d={line}
        fill="none"
        stroke={accent}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
        className={reduced || !active ? "" : "pv-draw"}
      />
      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
    </svg>
  );
}

/* ── Floating LIVE control panel — hero right column (from Cinematic) ──────── */
function LiveOpsPanel({ game }: { game: PreviewGame }) {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const totalSlots = 60;
  const players = useJitter(47, 3, seen, 2400, reduced);
  const filled = Math.min(totalSlots, players);
  const cpu = useCountUp(38, seen, 1200, reduced);
  const ping = useJitter(12, 2, seen, 3000, reduced);

  const logLines = [
    { t: "player connected · s.singe", c: "text-emerald-300" },
    { t: "player connected · DevReez", c: "text-emerald-300" },
    { t: "[Oxide] loaded 14 plugins", c: "text-slate-400" },
    { t: "map saved (0.4s) · autobackup ok", c: "text-slate-500" },
  ];

  return (
    <div ref={ref} className={reduced ? "" : "pv-float"}>
      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/85 shadow-2xl shadow-black/50 backdrop-blur-xl">
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{ background: `radial-gradient(45% 45% at 80% 0%, ${game.accent}33, transparent 70%)` }}
          aria-hidden
        />
        {/* header */}
        <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
          <GameLogo family={game.family} size={22} />
          <span className="ml-0.5 truncate text-[11px] font-medium text-slate-300">{game.worldName}</span>
          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            running
          </span>
        </div>

        <div className="space-y-4 p-4">
          {/* live stat row */}
          <div className="grid grid-cols-3 gap-2.5">
