                <Link href="/game-servers" className="btn-deploy mt-7 block px-4 py-3 text-center text-base">
                  Deploy {game.name} — {recommended.price}/mo
                </Link>
                <p className="mt-3 flex items-center justify-center gap-1.5 text-xs text-slate-500">
                  <IconBolt size={13} /> Instant setup · cancel anytime
                </p>
              </div>
              <a
                href="#plans"
                className="mt-4 flex items-center justify-center gap-1.5 text-sm font-semibold text-slate-400 transition-colors hover:text-white"
              >
                Compare all {game.plans.length} plans <span aria-hidden>↓</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* ══ HUD DEPLOY BEAT (console/terminal) ════════════════════════════════ */}
      <section className="relative isolate overflow-hidden py-24">
        <div
          className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-full"
          style={{
            background: `radial-gradient(55% 45% at 20% 0%, ${game.accent}1a, transparent 70%), radial-gradient(45% 40% at 85% 10%, ${game.glow}14, transparent 70%)`,
          }}
          aria-hidden
        />
        <div className="rail">
          <div className="mx-auto max-w-2xl text-center">
            <span className="eyebrow">Watch it deploy</span>
            <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
              From checkout to <span className="grad-text">connect-ready</span> in one boot sequence
            </h2>
            <p className="mt-4 text-lg text-slate-400">
              No SteamCMD, no patch-day babysitting. Order and the panel provisions, patches, and opens ports for you.
            </p>
          </div>
          <div className="mx-auto mt-12 max-w-5xl">
            <DeployBeat game={game} />
          </div>
        </div>
      </section>

      {/* ══ PLANS ═════════════════════════════════════════════════════════════ */}
      <section id="plans" className="tone-panel py-24">
        <div className="rail">
          <div className="mx-auto max-w-2xl text-center">
            <span className="eyebrow">Plans</span>
            <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">Pick your {game.name} plan</h2>
            <p className="mt-4 text-lg text-slate-400">
              Priced by RAM and slots. Every plan is instant, DDoS-protected, and resizable any time.
            </p>
          </div>
          <div className="mx-auto mt-12 grid max-w-5xl gap-5 md:grid-cols-3">
            {game.plans.map((p) => (
              <PlanCard key={p.id} game={game} p={p} />
            ))}
          </div>
        </div>
      </section>

      {/* ══ COMPACT 5-STAR REVIEWS ════════════════════════════════════════════ */}
      <section className="rail py-24">
        <div className="mx-auto flex max-w-2xl flex-col items-center text-center">
          <div className="flex items-center gap-3">
            <StarRow rating={5} size="text-base" />
            <span className="text-sm text-slate-400">
              <span className="font-semibold text-white">{game.ratingAvg} / 5</span> average · {game.ratingLabel}
            </span>
          </div>
        </div>
        <div className="mx-auto mt-10 grid max-w-5xl gap-4 md:grid-cols-3">
          {game.reviews.map((rv) => (
            <figure
              key={rv.id}
              className="flex flex-col rounded-2xl border border-white/[0.07] bg-navy-900/50 p-5 backdrop-blur-md"
            >
              <StarRow rating={rv.rating} />
              <blockquote className="mt-3 flex-1 text-sm leading-relaxed text-slate-300">&ldquo;{rv.quote}&rdquo;</blockquote>
              <figcaption className="mt-4 flex items-center gap-2.5 border-t border-white/[0.06] pt-3.5">
                <span
                  className="flex h-8 w-8 items-center justify-center rounded-full text-xs font-semibold text-white"
                  style={{ background: `linear-gradient(135deg, ${game.accent}, #3b82f6)` }}
                >
                  {rv.name.charAt(0)}
                </span>
                <span>
                  <span className="block text-xs font-semibold text-white">{rv.name}</span>
                  <span className="block text-[11px] text-slate-500">{rv.meta}</span>
                </span>
              </figcaption>
            </figure>
          ))}
        </div>
      </section>

      {/* ══ CINEMATIC CTA ═════════════════════════════════════════════════════ */}
      <section className="relative isolate overflow-hidden py-28">
        <div className="absolute inset-0 -z-20">
          {imgOk && (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={`/games/art/${game.artSlug}_hero.jpg`}
              alt=""
              aria-hidden
              className="h-full w-full scale-110 object-cover object-center opacity-40 blur-[2px]"
            />
          )}
        </div>
        <div className="pointer-events-none absolute inset-0 -z-10 bg-gradient-to-t from-navy-950 via-navy-950/80 to-navy-950/60" aria-hidden />
        <div className="rail text-center">
          <h2 className="mx-auto max-w-2xl text-3xl font-bold tracking-tight text-white sm:text-5xl">
            Your {game.name} server is <span className="grad-text">47 seconds</span> away.
          </h2>
          <p className="mx-auto mt-5 max-w-xl text-lg text-slate-300">
            Order, pick vanilla or modded, and share the connect string before your friends log on.
          </p>
          <div className="mt-9 flex flex-wrap justify-center gap-3">
            <Link href="/game-servers" className="btn-deploy px-7 py-3.5 text-base">
              Deploy {game.name} now
              <span className="dep-arrow" aria-hidden>→</span>
            </Link>
            <Link href="/pricing" className="btn-secondary px-6 py-3.5 text-base">
              See all pricing
            </Link>
          </div>
          <p className="mt-6 inline-flex items-center gap-2 text-sm text-slate-400">
            <IconClock size={15} style={{ color: game.accent }} /> Live in ~47 seconds · cancel anytime
          </p>
        </div>
      </section>
    </div>
  );
}

