import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
// Flagship "greatest-hits" merge of Directions A/B/C.
export const metadata: Metadata = {
  title: "Preview · Combined game landing (Flagship)",
  robots: { index: false, follow: false },
};

export default function Page() {
  return <GameLandingCombined game={PREVIEW_GAMES.rust} />;
}

import { chromium } from "playwright";

const URL = "http://localhost:3778/preview/game-combined";
const OUT = "/opt/nxeon-staging/.design-previews";

const shots = [
  { name: "combined-desktop-1440", width: 1440, height: 900, dsf: 1 },
  { name: "combined-mobile-390", width: 390, height: 844, dsf: 2 },
];

const browser = await chromium.launch();
for (const s of shots) {
  const ctx = await browser.newContext({
    viewport: { width: s.width, height: s.height },
    deviceScaleFactor: s.dsf,
  });
  const page = await ctx.newPage();
  await page.goto(URL, { waitUntil: "networkidle", timeout: 60000 });
  // let hero art load + entrance animations settle
  await page.waitForTimeout(2500);
  // full-page capture
  await page.screenshot({ path: `${OUT}/${s.name}-full.png`, fullPage: true });
  // above-the-fold hero capture
  await page.screenshot({ path: `${OUT}/${s.name}-hero.png`, fullPage: false });
  console.log(`shot ${s.name} (${s.width}x${s.height})`);
  await ctx.close();
}
await browser.close();
console.log("done");
